#include "stdlib/blas/base/dtrmv.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/ndarray/base/assert/is_row_major.h"

/**
* Performs one of the matrix-vector operations `x = A*x` or `x = A^T*x` using alternative indexing semantics, where `x` is an `N` element vector and `A` is an `N` by `N` unit, or non-unit, upper or lower triangular matrix.
*
* @param uplo      specifies whether `A` is an upper or lower triangular matrix
* @param trans     specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param diag      specifies whether `A` has a unit diagonal
* @param N         number of elements along each dimension of `A`
* @param A         input matrix
* @param strideA1  stride of the first dimension of `A`
* @param strideA1  stride of the second dimension of `A`
* @param offsetA   starting index for `A`
* @param x         input vector
* @param strideX   `x` stride length
* @param offsetX   starting index for `x`
* @return          output value
*/
void API_SUFFIX(c_dtrmv_ndarray)( const CBLAS_UPLO uplo, const CBLAS_TRANSPOSE trans, const CBLAS_DIAG diag, const CBLAS_INT N, const double *A, const CBLAS_INT strideA1, const CBLAS_INT strideA2, const CBLAS_INT offsetA, double *x, const CBLAS_INT strideX, const CBLAS_INT offsetX ) {
	CBLAS_INT nonunit;
	int64_t sa[ 2 ];
	CBLAS_INT isrm;
	CBLAS_INT ix0;
	CBLAS_INT ix1;
	CBLAS_INT sa0;
	CBLAS_INT sa1;
	CBLAS_INT i0;
	CBLAS_INT i1;
	CBLAS_INT ox;
	CBLAS_INT oa;
	double tmp;

	// Note on variable naming convention: sa#, ix#, i# where # corresponds to the loop number, with `0` being the innermost loop...

	// Note on variable naming convention: sa#, ix#, i# where # corresponds to the loop number, with `0` being the innermost loop...

	// Perform input argument validation...
	if ( uplo != CblasLower && uplo != CblasUpper ) {
		c_xerbla( 1, "c_dtrmv_ndarray", "Error: invalid argument. First argument must specify whether the lower or upper triangular matrix is supplied. Value: `%d`.", uplo );
		return;
	}
	if ( trans != CblasTrans && trans != CblasConjTrans && trans != CblasNoTrans ) {
		c_xerbla( 2, "c_dtrmv_ndarray", "Error: invalid argument. Second argument must be a valid transpose operation. Value: `%d`.", trans );
		return;
	}
	if ( diag != CblasNonUnit && diag != CblasUnit ) {
		c_xerbla( 3, "c_dtrmv_ndarray", "Error: invalid argument. Third argument must be a valid diagonal type. Value: `%d`.", diag );
		return;
	}
	if ( N < 0 ) {
		c_xerbla( 4, "c_dtrmv_ndarray", "Error: invalid argument. Fourth argument must be a nonnegative integer. Value: `%d`.", N );
		return;
	}
	if ( strideA1 == 0 ) {
		c_xerbla( 6, "c_dtrmv_ndarray", "Error: invalid argument. Sixth argument must be a nonzero. Value: `%d`.", strideA1 );
		return;
	}
	if ( strideA2 == 0 ) {
		c_xerbla( 7, "c_dtrmv_ndarray", "Error: invalid argument. Seventh argument must be a nonzero. Value: `%d`.", strideA2 );
		return;
	}
	if ( strideX == 0 ) {
		c_xerbla( 10, "c_dtrmv_ndarray", "Error: invalid argument. Tenth argument must be a nonzero. Value: `%d`.", strideX );
		return;
	}
	// Check whether we can avoid computation altogether...
	if ( N == 0 ) {
		return;
	}
	nonunit = ( diag == CblasNonUnit );
	// Extract loop variables for purposes of loop interchange: dimensions and loop offset (pointer) increments...
	sa[ 0 ] = strideA1;
	sa[ 1 ] = strideA2;
	isrm = stdlib_ndarray_is_row_major( 2, sa );
	if ( isrm ) {
		sa0 = strideA2;
		sa1 = strideA1;
	} else {
		sa0 = strideA1;
		sa1 = strideA2;
	}
	ox = offsetX;

	if (
		( !isrm && trans == CblasNoTrans && uplo == CblasUpper ) ||
		( isrm && trans != CblasNoTrans && uplo == CblasLower )
	) {
		ix1 = ox;
		for ( i1 = 0; i1 < N; i1++ ) {
			if ( x[ ix1 ] != 0.0 ) {
				tmp = x[ ix1 ];
				oa = offsetA + (sa1*i1);
				ix0 = ox;
				for ( i0 = 0; i0 < i1; i0++ ) {
					x[ ix0 ] += tmp * A[ oa+(sa0*i0) ];
					ix0 += strideX;
				}
				if ( nonunit ) {
					x[ ix1 ] *= A[ oa+(sa0*i1) ];
				}
			}
			ix1 += strideX;
		}
		return;
	}
	if (
		( !isrm && trans == CblasNoTrans && uplo == CblasLower ) ||
		( isrm && trans != CblasNoTrans && uplo == CblasUpper )
	) {
		ox += ( N - 1 ) * strideX;
		ix1 = ox;
		for ( i1 = N-1; i1 >= 0; i1-- ) {
			if ( x[ ix1 ] != 0.0 ) {
				tmp = x[ ix1 ];
				oa = offsetA + (sa1*i1);
				ix0 = ox;
				for ( i0 = N-1; i0 > i1; i0-- ) {
					x[ ix0 ] += tmp * A[ oa+(sa0*i0) ];
					ix0 -= strideX;
				}
				if ( nonunit ) {
					x[ ix1 ] *= A[ oa+(sa0*i1) ];
				}
			}
			ix1 -= strideX;
		}
		return;
	}
	if (
		( !isrm && trans != CblasNoTrans && uplo == CblasUpper ) ||
		( isrm && trans == CblasNoTrans && uplo == CblasLower )
	) {
		ix1 = ox + ( ( N - 1 ) * strideX );
		for ( i1 = N-1; i1 >= 0; i1-- ) {
			tmp = x[ ix1 ];
			oa = offsetA + (sa1*i1);
			ix0 = ix1;
			if ( nonunit ) {
				tmp *= A[ oa+(sa0*i1) ];
			}
			for ( i0 = i1-1; i0 >= 0; i0-- ) {
				ix0 -= strideX;
				tmp += x[ ix0 ] * A[ oa+(sa0*i0) ];
			}
			x[ ix1 ] = tmp;
			ix1 -= strideX;
		}
		return;
	}
	// ( !isrm && trans != CblasNoTrans && uplo == CblasLower ) || ( isrm && trans == CblasNoTrans && uplo == CblasUpper )
	ix1 = ox;
	for ( i1 = 0; i1 < N; i1++ ) {
		tmp = x[ ix1 ];
		oa = offsetA + (sa1*i1);
		ix0 = ix1;
		if ( nonunit ) {
			tmp *= A[ oa+(sa0*i1) ];
		}
		for ( i0 = i1+1; i0 < N; i0++ ) {
			ix0 += strideX;
			tmp += x[ ix0 ] * A[ oa+(sa0*i0) ];
		}
		x[ ix1 ] = tmp;
		ix1 += strideX;
	}
	return;
}
